--"C:\Program Files\PostgreSQL\14\bin\shp2pgsql.exe" -s 4326 -c -g geom -I "C:\Users\jraitif\Documents\QGis_EDA\shp_historique_complet_repang\historique_complet_repang.shp" france.temp_alvinage_shp >temp_alvinage.sql


SET CLIENT_ENCODING TO UTF8;
SET STANDARD_CONFORMING_STRINGS TO ON;
BEGIN;
CREATE TABLE "france"."temp_alvinage_shp" (gid serial,
"id" float8,
"id_projet" float8,
"projet" varchar(254),
"id_sousprj" float8,
"sousprojet" varchar(254),
"annee" float8,
"qdev_kg" varchar(254),
"nb_civelle" float8,
"point_uniq" varchar(254),
"x_(wgs84)" numeric,
"y_(wgs84)" numeric);
ALTER TABLE "france"."temp_alvinage_shp" ADD PRIMARY KEY (gid);
SELECT AddGeometryColumn('france','temp_alvinage_shp','geom','4326','POINT',2, true);
CREATE INDEX ON "france"."temp_alvinage_shp" USING GIST ("geom");
COMMIT;
ANALYZE "france"."temp_alvinage_shp";
